import{_ as e,c as t,o as s,ai as c}from"./chunks/framework.B63Sb1io.js";const m=JSON.parse('{"title":"MkDocs","titleTemplate":"静态文档页面构建工具","description":"MkDocs","frontmatter":{"title":"MkDocs","titleTemplate":"静态文档页面构建工具","description":"MkDocs","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true},"headers":[],"relativePath":"project/blog/SSG/MkDocs.md","filePath":"project/blog/SSG/MkDocs.md","lastUpdated":1755592887000}'),d={name:"project/blog/SSG/MkDocs.md"};function a(r,o,l,i,n,k){return s(),t("div",null,o[0]||(o[0]=[c('<h1 id="mkdocs" tabindex="-1">MkDocs <a class="header-anchor" href="#mkdocs" aria-label="Permalink to &quot;MkDocs&quot;">​</a></h1><h2 id="一、mkdocs-简介" tabindex="-1">一、MkDocs 简介 <a class="header-anchor" href="#一、mkdocs-简介" aria-label="Permalink to &quot;一、MkDocs 简介&quot;">​</a></h2><p>MkDocs 是一个<strong>快速、简单、优雅的静态网站生成器</strong>，专门为创建<strong>项目文档</strong>而设计。它的核心思想是：让你能够专注于编写内容（使用 Markdown），而它负责将内容构建成一个美观、可浏览的静态网站。</p><p>官方网址：www.mkdocs.org</p><p>![[22.png]]</p><h2 id="二、部署流程" tabindex="-1">二、部署流程 <a class="header-anchor" href="#二、部署流程" aria-label="Permalink to &quot;二、部署流程&quot;">​</a></h2><ol><li><strong>安装：</strong> <code>pip install mkdocs</code> (需要 Python 环境)</li><li><strong>创建新项目：</strong> <code>mkdocs new my-docs-site</code></li><li><strong>进入项目目录：</strong> <code>cd my-docs-site</code></li><li><strong>编辑内容：</strong> 在 <code>docs/</code> 目录下编写 Markdown (<code>.md</code>) 文件。</li><li><strong>配置导航：</strong> 编辑 <code>mkdocs.yml</code> 文件，定义 <code>site_name</code> 和 <code>nav</code> 结构。</li><li><strong>本地预览：</strong> 运行 <code>mkdocs serve</code>，然后在浏览器中访问 <code>http://localhost:8000</code>。</li><li><strong>构建站点：</strong> 运行 <code>mkdocs build</code> (输出到 <code>site/</code> 目录)。</li><li><strong>部署：</strong> 将 <code>site/</code> 目录的内容上传到你的托管平台。</li></ol>',7)]))}const g=e(d,[["render",a]]);export{m as __pageData,g as default};
